import {audioFiles} from './audio';
import {lessons,allLessons,palette} from './curriculum';
const $=s=>document.querySelector(s), main=$('#main');

const trainSVG=`<svg viewBox="0 0 180 130" role="img" aria-label="قطار بيكسا"><path d="M23 97H163L172 109H12Z" fill="#d7ac65"/><rect x="70" y="48" width="70" height="48" rx="13" fill="#217e8b" stroke="#e8bd77" stroke-width="3"/><path d="M23 23H73V91H23Z" fill="#1e697c" stroke="#e8bd77" stroke-width="3"/><path d="M15 19H79" stroke="#edc887" stroke-width="8" stroke-linecap="round"/><rect x="35" y="33" width="23" height="24" rx="3" fill="#a8dfdf"/><path d="M122 47V19H137V50" fill="#204858" stroke="#e8bd77" stroke-width="3"/><circle cx="143" cy="70" r="17" fill="#ebbd6c"/><circle cx="145" cy="70" r="10" fill="#fff0b9"/><circle cx="42" cy="104" r="19" fill="#26364b" stroke="#e6b86b" stroke-width="5"/><circle cx="100" cy="104" r="19" fill="#26364b" stroke="#e6b86b" stroke-width="5"/><path d="M42 104H100" stroke="#d7e3df" stroke-width="4"/><text x="94" y="75" text-anchor="middle" fill="#ffe3a5" font-size="11" font-family="Arial">PIXA</text></svg>`;
const lionSVG=`<svg viewBox="0 0 120 120" role="img" aria-label="أسد بيكسا، دليل رحلة الإنجليزية"><path d="M20 27L37 15L53 18L69 10L83 22L101 26L103 44L112 60L102 75L99 94L81 97L65 110L48 101L29 101L23 84L9 71L16 53L13 37Z" fill="#a96b34" stroke="#f0bd68" stroke-width="3"/><circle cx="28" cy="39" r="12" fill="#e8ac55"/><circle cx="92" cy="39" r="12" fill="#e8ac55"/><path d="M29 51Q27 27 60 26Q94 27 92 59L87 81Q80 99 60 99Q39 98 32 81Z" fill="#f4cb7a"/><path d="M35 53Q44 45 51 51M69 51Q78 45 86 53" fill="none" stroke="#68462e" stroke-width="4" stroke-linecap="round"/><ellipse cx="44" cy="59" rx="4" ry="6" fill="#27374a"/><ellipse cx="77" cy="59" rx="4" ry="6" fill="#27374a"/><circle cx="45" cy="57" r="1.3" fill="white"/><circle cx="78" cy="57" r="1.3" fill="white"/><ellipse cx="60" cy="77" rx="23" ry="16" fill="#fff0ca"/><path d="M51 69Q60 64 69 69L60 78Z" fill="#68462e"/><path d="M60 77V83Q49 91 43 81M60 83Q71 91 78 81" fill="none" stroke="#68462e" stroke-width="2.5" stroke-linecap="round"/><path d="M43 101L60 111L79 101" fill="#30899a" stroke="#8de4d8" stroke-width="3"/><circle cx="60" cy="108" r="4" fill="#f0c678"/></svg>`;
function guide(words){return `<aside class="lion-guide">${lionSVG}<p><small>أسد بيكسا · صاحبك في رحلة الإنجليزية</small><span>${words}</span></p></aside>`}
const waveSVG=`<svg viewBox="0 0 140 110" aria-hidden="true"><path d="M55 98L29 66Q24 57 32 54Q38 51 49 66L35 22Q33 12 42 12Q49 12 58 46L52 11Q51 2 60 3Q68 4 71 43L72 12Q73 3 81 7Q88 10 86 47L93 25Q96 17 103 22Q110 28 99 65L93 88Q82 108 55 98Z" fill="#efbe91" stroke="#be825e" stroke-width="3"/><path d="M15 25Q3 40 9 55M117 13Q133 28 128 44" fill="none" stroke="#eac57b" stroke-width="5" stroke-linecap="round"/></svg>`;
const snowSVG=`<svg viewBox="0 0 120 100" aria-hidden="true"><g stroke="#d5f2ff" stroke-width="7" stroke-linecap="round"><path d="M60 10V90M25 30L95 70M25 70L95 30M50 18L60 28L70 18M50 82L60 72L70 82M28 42L39 38L38 25M82 75L81 62L93 58M28 58L39 62L38 75M82 25L81 38L93 42"/></g></svg>`;

const initial=await api('bootstrap').catch(()=>{document.querySelector('#main').textContent='الدخول أو الحفظ مش متاح. ارجع للمنصة وسجّل الدخول تاني.';throw new Error('account_unavailable')});
let saved={done:initial.completed,best:initial.best||0},storageOK=true,attempt=null,serverResult=null;
async function api(path,body){const response=await fetch('/api/english-adventure/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(!response.ok)throw new Error('حسابك أو الحفظ غير متاح. ارجع وسجّل الدخول تاني، من غير ما تقفل الخطوة دي.');return response.json()}
let state={screen:'map',lesson:null,index:0,words:[],load:0,feedback:null,score:0,missed:[],assisted:false,heard:false};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));


let currentAudio=null,audioGeneration=0;
function stopAudio(){audioGeneration++;if(currentAudio){currentAudio.pause();currentAudio.onended=null;currentAudio=null}}
function speak(text,onDone){
 const path=audioFiles[text];
 if(!path){notice('الصوت مش جاهز','العبارة دي لسه مفيش لها تسجيل. استخدم بديل القراءة لو متاح.');return false}
 try{stopAudio();const generation=audioGeneration;currentAudio=new Audio(path);currentAudio.onended=()=>{if(generation===audioGeneration)onDone?.()};currentAudio.onerror=()=>{const status=$('#audio-status');if(status)status.textContent='تعذّر تشغيل التسجيل. جرّب تاني أو استخدم بديل القراءة.'};currentAudio.play().catch(()=>{const status=$('#audio-status');if(status)status.textContent='المتصفح منع الصوت. اضغط اسمع تاني أو استخدم بديل القراءة.'});return true}catch{return false}
}

function notice(title,body){$('#dialog-body').innerHTML=`<h2>${title}</h2><p>${body}</p>`;$('#dialog').showModal()}
function heading(){main.focus({preventScroll:true})}
function reviewMode(){return !!state.lesson?.tasks[state.index]?.review}
function progress(){return lessons.filter(l=>saved.done.includes(l.id)).length}
function renderMap(){stopAudio();state.screen='map';state.lesson=null;document.title='Pixa World | جزيرة البدايات';main.innerHTML=`<section class="map-intro"><div><p class="eyebrow">رحلة صغيرة، اكتشاف كبير</p><h1>جزيرة البدايات</h1><p class="intro">شغّل قطار الكلمات، قابل أصدقاءك، واجمع نور الجزيرة.</p></div><div class="map-progress"><span class="star">✦</span><div><strong>${progress()} / ${lessons.length}</strong><small>محطات اكتمل تدريبها</small></div></div></section>${guide('نكتشف الجزيرة سوا، محطة ورا محطة. جاهز نركب قطار الكلمات؟')}<section class="island-map" aria-label="محطات جزيرة البدايات"><img src="/api/english-adventure/assets/islands.webp" class="map-art" alt="جزر خيالية متصلة بسكة قطار، فيها ميناء وحديقة وبيت ومرصد"><div class="map-shade"></div>${lessons.map((l,i)=>`<button class="station ${saved.done.includes(l.id)?'completed':!initial.admin&&lessons.slice(0,i).some(p=>!saved.done.includes(p.id))?'locked':''}" style="--x:${l.x}%;--y:${l.y}%;--accent:${l.color}" data-lesson="${l.id}"><span class="station-circle">${saved.done.includes(l.id)?'✓':!initial.admin&&lessons.slice(0,i).some(p=>!saved.done.includes(p.id))?'<svg viewBox="0 0 24 24" width="23" height="23" aria-label="مقفولة"><path d="M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5z" fill="none" stroke="currentColor" stroke-width="2.2"/><circle cx="12" cy="15" r="1.4" fill="currentColor"/></svg>':i+1}</span><span class="station-title">${l.name}</span><small lang="en" dir="ltr">${l.en}</small></button>`).join('')}<div class="map-caption"><span>✦</span> كل محطة مغامرة. مفيش مؤقّت ولا خسارة محاولات.</div></section><section class="journey-bottom"><div class="next-stop"><div class="mini-icon">${trainSVG}</div><div><small>محطتك الجاية</small><h2>${(lessons.find(l=>!saved.done.includes(l.id))||lessons[0]).name}</h2><p>${(lessons.find(l=>!saved.done.includes(l.id))||lessons[0]).goal}</p></div><button class="primary" data-lesson="${(lessons.find(l=>!saved.done.includes(l.id))||lessons[0]).id}" >${progress()===5?'راجع والعب':'يلا نبدأ'} <span>←</span></button></div><div class="finale-card"><span class="crown">♛</span><div><strong>تاج الجزيرة</strong><small>${progress()===5?'كمّلت دروس الخريطة الخمسة. تقدر ترجع لأي محطة.':'التحدّي الختامي جوا الدرس الخامس. كمّل الرحلة عشان تجمع التاج.'}</small></div><span>${progress()===5?'✦':'◇'}</span></div></section><footer><span>تعلم تأسيسي للأطفال · التقدّم مرتبط بحسابك</span><button class="text-button" id="about">للأهل والمعلّم</button></footer>`;
main.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>overview(b.dataset.lesson));$('#about').onclick=about;heading()}
async function overview(id){const ix=allLessons.findIndex(l=>l.id===id);if(!initial.admin&&allLessons.slice(0,ix).some(l=>!saved.done.includes(l.id))){notice('المحطة مقفولة','كمّل المحطات اللي قبلها بالترتيب.');return}stopAudio();let l;try{l=await api('lesson?id='+encodeURIComponent(id))}catch(e){notice('المحطة مش متاحة',e.message);return}state={screen:'overview',lesson:l,index:0,words:[],load:0,feedback:null,score:0,missed:[],assisted:false,heard:false};main.innerHTML=`<section class="lesson-intro"><button class="text-button back" id="back">→ الخريطة</button>${guide('اسمع وجرّب براحتك. أنا معاك في كل محطة!')}<div class="intro-grid"><div><p class="eyebrow">${id==='body'?'تحدّي الجزيرة':'محطة جديدة في رحلتك'}</p><h1>${l.name}</h1><h2 lang="en" dir="ltr">${l.en}</h2><p>${l.goal}</p><p class="quiet">${id==='body'?'نتعلم أجزاء الجسم، وبعدها تحدّي مراجعة جوا نفس الدرس. النجاح من ٨ إجابات مستقلة من ١٠ في التحدّي.':'اسمع الكلمات وجربها، وبعدين استخدمها في اللعبة. كل سؤال تقدر تحاول فيه تاني.'}</p><button class="primary" id="start">${id==='body'?'ابدأ التحدّي':'اركب القطار'} ←</button></div><div class="intro-postcard"><img src="/api/english-adventure/assets/harbour.webp" alt="قطار بيكسا مستعد للرحلة في الميناء"><span>تذكرتك للاكتشاف ✦</span></div></div>${l.vocab.length?`<section class="phrasebook"><h2>كلمات الرحلة</h2><p class="quiet">اضغط على أي عبارة عشان تسمعها. جرّب تقولها بصوتك، من غير تسجيل.</p><div class="vocab-grid">${l.vocab.map(([en,ar])=>`<button class="vocab" data-say="${esc(en)}"><span dir="ltr" lang="en">${esc(en)}</span><small>${ar}</small><span class="speaker">◖))</span></button>`).join('')}</div><p id="audio-status" class="quiet" role="status"></p></section>`:''}</section>`;$('#back').onclick=renderMap;$('#start').onclick=async()=>{try{$('#start').disabled=true;attempt=await api('attempt',{action:'begin',lessonId:l.id});serverResult=null;renderTask()}catch(e){$('#start').disabled=false;notice('الرحلة لسه مبدأتش',e.message)}};main.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(b.dataset.say));heading()}
function character(){return `<svg class="body-character" viewBox="0 0 300 340" role="img" aria-label="شخصية اللعبة"><path d="M100 160L50 230M200 160L250 230" stroke="#e8ae81" stroke-width="24" stroke-linecap="round"/><path d="M125 240L110 310M175 240L190 310" stroke="#35486b" stroke-width="27" stroke-linecap="round"/><path d="M102 155Q150 125 198 155L195 245H105Z" fill="#1c9caa"/><circle cx="150" cy="89" r="57" fill="#f3bd90"/><path d="M95 75Q90 12 154 25Q215 18 207 83L184 54L162 65L137 45L111 78" fill="#453744"/><circle cx="130" cy="88" r="5" fill="#24304a"/><circle cx="170" cy="88" r="5" fill="#24304a"/><path d="M134 113Q151 129 169 111" fill="none" stroke="#ad594a" stroke-width="5" stroke-linecap="round"/><circle cx="150" cy="101" r="4" fill="#d98f64"/><path d="M95 315H120M181 315H206" stroke="#eeac49" stroke-width="19" stroke-linecap="round"/></svg>`}
function taskScene(t){if(t.type==='load')return `<div class="cargo-scene"><div class="crane" aria-hidden="true">♜<span>✦</span></div><div class="cargo"><div class="cargo-stars" aria-label="${state.load} نجوم في العربة">${Array.from({length:state.load},(_,i)=>`<button class="cargo-object" data-star="${i}" aria-label="شيل النجمة ${i+1}">✦</button>`).join('')||'<span class="cargo-empty">0</span>'}</div><div class="wagon">●<span>PIXA</span>●</div></div><span class="engine" aria-hidden="true">${trainSVG}</span></div><div class="cargo-controls"><button id="minus" class="icon-button" aria-label="شيل نجمة" ${state.load===0?'disabled':''}>−</button><output aria-live="polite">${state.load}</output><button id="plus" class="icon-button" aria-label="حمّل نجمة" ${state.load===10?'disabled':''}>✦ +</button></div><button id="submit-load" class="primary">أرسل القطار ←</button>`;
if(t.type==='order')return `<div class="sentence-track" aria-label="جملتك" dir="ltr">${state.words.length?state.words.map((ix,j)=>`<button class="word placed" data-remove="${j}">${esc(t.words[ix])} <small>×</small></button>`).join(''):'<span>اختار الكلمات بالترتيب</span>'}</div><div class="word-bank" dir="ltr">${t.words.map((w,i)=>`<button class="word" data-word="${i}" ${state.words.includes(i)?'disabled':''}>${esc(w)}</button>`).join('')}</div><button id="submit-order" class="primary" ${state.words.length!==t.words.length?'disabled':''}>شغّل الجملة ←</button>`;
if(t.type==='body')return `<div class="body-game">${character()}<div class="body-targets">${[['head','الرأس'],['hand','اليد'],['foot','القدم']].map(([p,ar])=>`<button class="body-target ${p}" data-value="${p}" aria-label="${ar}"><span class="target-dot">+</span><span>${t.review?'':ar}</span></button>`).join('')}</div></div>`;
if(t.type==='paint')return `<div class="paint-scene"><svg viewBox="0 0 300 190" role="img" aria-label="قارب مستني لون شراعه"><path d="M148 17V147H48Z" fill="${state.paint||'#f3ead7'}" stroke="#fae1a5" stroke-width="3"/><path d="M158 45V147H246Z" fill="${state.paint||'#f3ead7'}" opacity=".85"/><path d="M32 154H270L239 183H65Z" fill="#a16b36"/><path d="M149 9V157" stroke="#6f4a2a" stroke-width="8"/></svg></div><div class="paint-palette">${t.options.map(o=>`<button class="paint-pot" data-value="${o}" style="--paint:${palette[o]}"><span></span><b lang="en">${o}</b></button>`).join('')}</div>`;
return `${t.scene?`<div class="story-visual" aria-hidden="true">${t.scene==='wave'?waveSVG:t.scene==='bye'?trainSVG:t.scene==='snow'?snowSVG:character()}</div>`:'<div class="signal-light" aria-hidden="true">✦</div>'}<div class="answers">${t.options.map((o,i)=>`<button class="answer" data-value="${esc(o)}"><span class="answer-number">${i+1}</span><span dir="auto">${esc(o)}</span><span>→</span></button>`).join('')}</div>`}
function renderTask(){const l=state.lesson,t=l.tasks[state.index];state.screen='task';document.title=`${l.name} | Pixa World`;main.innerHTML=`<section class="game"><div class="game-toolbar"><button class="text-button" id="exit">→ الخريطة</button><span>${l.name}</span><span class="task-counter" dir="ltr">${state.index+1} / ${l.tasks.length}</span></div><div class="progress-track"><div style="width:${(state.index/l.tasks.length)*100}%"></div></div><div class="game-world ${state.feedback?.correct?'solved':''}"><div class="game-question"><div class="lion-task" aria-hidden="true">${lionSVG}</div><p class="eyebrow">${reviewMode()?'الدرس الخامس · تحدّي المراجعة':'جرّب واكتشف'}</p><h1 dir="ltr" lang="en">${t.prompt}</h1><p>${t.ar}</p>${t.spoken?`<button id="listen" class="listen-button">◖)) اسمع المطلوب</button><button id="reading" class="text-button reading-help">بديل القراءة</button><div id="reading-text" class="reading-text" hidden dir="ltr" lang="en">${esc(t.spoken)}</div><p id="audio-status" class="quiet" role="status"></p>`:''}</div><div class="play-area ${t.type}">${taskScene(t)}</div><div class="feedback ${state.feedback?.correct?'success':'retry'}" role="status">${state.feedback?`<span class="lion-feedback">${lionSVG}</span><div><strong>${state.feedback.correct?'أحسنت! القطار جاهز.':reviewMode()?'اتسجلت إجابتك.':'لسه مش دي. جرّب تاني بهدوء.'}</strong><p>${state.feedback.correct?'خطوة جديدة في رحلتك.':reviewMode()?'هنراجع النتيجة في نهاية الرحلة.':'مفيش مشكلة، راجع المطلوب وخد وقتك.'}</p></div>${state.feedback.correct||reviewMode()?'<button class="primary" id="next">كمّل ←</button>':''}`:'<span class="hint-dot">✧</span><p>خد وقتك. كل اختيار خطوة للتعلّم.</p>'}</div></div></section>`;
$('#exit').onclick=()=>{if(state.pending){notice('الحفظ شغّال','استنى تأكيد حفظ الإجابة قبل ما ترجع للخريطة.');return}if(state.index>0)notice('تقدم المحطة مش محفوظ لسه','المحطة بتتحفظ لما تكمّلها. تقدر تكمّل دلوقتي أو ترجع للخريطة من الزر اللي تحت. <button id="leave-now" class="text-button">ارجع للخريطة</button>');else renderMap();setTimeout(()=>{$('#leave-now')&&($('#leave-now').onclick=()=>{$('#dialog').close();renderMap()})},0)};
$('#listen')&&($('#listen').onclick=()=>{const started=speak(t.spoken,()=>{state.heard=true;const status=$('#audio-status');if(status)status.textContent='سمعت المطلوب؟ اختار الإجابة.';main.querySelectorAll('[data-value]').forEach(b=>b.disabled=false)});if(started)$('#audio-status').textContent='اسمع للآخر، وبعدين اختار. لو مفيش صوت استخدم بديل القراءة.'});$('#reading')&&($('#reading').onclick=()=>{$('#reading-text').hidden=false;state.assisted=true;main.querySelectorAll('[data-value]').forEach(b=>b.disabled=false);$('#audio-status').textContent='ده بديل قراءة. السؤال ده مش هيُحسب كاختبار استماع مستقل.'});
const locked=state.feedback&&(state.feedback.correct||reviewMode());const awaitingAudio=t.listening&&!state.heard&&!state.assisted;
main.querySelectorAll('[data-value]').forEach(b=>{b.disabled=!!locked||awaitingAudio;b.onclick=()=>{if(t.type==='paint')state.paint=b.dataset.value;submit(b.dataset.value)}});
main.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{state.load=Math.max(0,state.load-1);state.feedback=null;renderTask()});
$('#plus')&&($('#plus').onclick=()=>{state.load=Math.min(10,state.load+1);state.feedback=null;renderTask();$('#plus').focus()});$('#minus')&&($('#minus').onclick=()=>{state.load=Math.max(0,state.load-1);state.feedback=null;renderTask();$('#minus').focus()});$('#submit-load')&&($('#submit-load').onclick=()=>submit(state.load));
main.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{state.words.push(Number(b.dataset.word));state.feedback=null;renderTask();(main.querySelector('[data-word]:not(:disabled)')||$('#submit-order')).focus()});main.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.words.splice(Number(b.dataset.remove),1);state.feedback=null;renderTask();main.querySelector('[data-word]:not(:disabled)')?.focus()});$('#submit-order')&&($('#submit-order').onclick=()=>submit(state.words.map(i=>t.words[i]).join(' ')));
if(locked){main.querySelectorAll('.play-area button').forEach(b=>b.disabled=true)}
$('#next')&&($('#next').onclick=()=>{stopAudio();state.index++;state.load=0;state.words=[];state.paint=null;state.feedback=null;state.assisted=false;state.heard=false;if(state.index>=l.tasks.length)finish();else {renderTask();heading()}})}
